(function(root){'use strict';const F=root.NutriFamily,E=root.NutriRegistrationEntry;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function mount(){const page=document.querySelector('#family-app'),S=E.store;let state=null,active=true,busy=false,dirty=false,stale=false,unsub;const dirtyForms=new Set();
const guard=()=>active;const status=s=>{page.querySelector('[role=status]').textContent=s;};
function render(next){state=F.clone(next);stale=false;dirty=false;dirtyForms.clear();const f=state.health.family,p=f?F.projection(state):null;page.innerHTML=`<header><a href="intake.html">‹ 营养摄入</a><h1>合成家庭</h1><p>仅在本机演示；请勿输入真实姓名或健康资料。</p></header><p>家庭页面当前选择不会改变其他页面的沈先生本人视图。</p>${p?`<section><label>查看日期<input data-date type="date" value="${p.date}"></label><h2>${esc(p.name)}</h2><p>${p.date} · ${p.meals.length} 条合成餐食</p><div class="family-members">${p.members.map(m=>`<article><strong>${esc(m.name)}</strong><small>${m.active?'可选成员':'归档保留'}</small>${m.active?`<button data-action="select" data-id="${m.id}" ${m.id===p.memberId?'disabled':''}>${m.id===p.memberId?'当前成员':'查看'}</button><form data-form="rename" data-id="${m.id}"><label>改名<input name="name" maxlength="40" required value="${esc(m.name)}"></label><button>保存名称</button></form>${m.id==='self'?'':`<button data-action="delete" data-id="${m.id}">归档成员</button>`}`:`<button data-action="restore" data-id="${m.id}">恢复成员</button>`}</article>`).join('')}</div></section><section><h2>新增合成成员</h2><form data-form="add"><label>演示名称<input name="name" maxlength="40" required placeholder="例如：合成家人 A"></label><button>新增空白成员</button></form><p>不会继承沈先生的餐食、指标、随访或提醒。</p></section><section><h2>这天的餐食</h2>${p.meals.length?`<ul>${p.meals.map(m=>`<li>${esc(m.time)} ${esc(m.name)} · ${m.kcal===null||m.kcal===undefined?'热量未知':esc(m.kcal)+' kcal（合成）'}</li>`).join('')}</ul>`:'<p>暂无记录；未记录不代表未进食。</p>'}<form data-form="meal"><label>合成菜名<input name="name" required maxlength="40"></label><label>餐次<select name="slot"><option value="breakfast">早餐</option><option value="lunch">午餐</option><option value="dinner">晚餐</option><option value="snack">加餐</option></select></label><label>时间<input name="time" type="time" value="12:00" required></label><label><input name="consent" type="checkbox" required>确认仅为合成数据，归属 ${esc(p.name)} / ${p.date}</label><p>份量与营养未知，不从菜名推算。</p><button>确认记录</button></form></section>`:`<section><h2>保留本人，新增空白家庭</h2><p>首次启用保留当前沈先生资料快照，不改原本人记录。</p><button data-action="init">启用合成家庭</button></section>`}<button data-refresh>放弃未保存填写并刷新</button><p role="status" aria-live="polite"></p><footer><a href="settings.html">整个合成账号重置 / 回退说明</a><p>归档保留成员数据；家庭资料随整个账号重置。账户撤销能力以共享入口显示为准。</p></footer>`;}
function disabled(v){page.querySelectorAll('button,input,select').forEach(x=>{if(!x.hasAttribute('data-refresh'))x.disabled=v||stale||E.hasPending();});}
async function execute(command){if(busy||stale||E.hasPending()||!state)return;const base=F.clone(state);let planned;try{planned=F.candidate(base,command);}catch(e){status(e.message);return;}busy=true;disabled(true);const context=F.context(base);
try{await E.execute({kind:'family:'+command.type,context,input:planned.input,guard,
run:({input,context})=>S.transact(d=>{F.mutate(d,input);return null;},{context,expectedRevision:context.revision,guard,reason:'family:'+command.type}),
onSuccess:receipt=>{if(!active)return;try{const saved=F.verify(base,planned.state,receipt);if(!F.same(saved,S.read()))throw Error('已有更新版本，请刷新核对；不清空当前填写');render(saved);status(receipt.persistent?'已保存到本机合成账号。':'仅本页临时保存；刷新或离开即丢失。');}catch(e){stale=true;status(e.message);}},
onError:e=>{if(active)status(e.message+'；填写保留，请在共享入口核对原操作。');},
reconcile:({state:now})=>({status:F.same(now,base)?'base':'changed',message:'请核对当前记录；记录匹配不替代原操作回执。'})});}catch(e){if(active)status(e.message+'；填写保留。');}finally{busy=false;if(active)disabled(false);}}
page.addEventListener('input',e=>{dirty=true;const form=e.target.closest?.('form');if(form)dirtyForms.add(form);});
page.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!form.reportValidity()||busy||stale||E.hasPending())return;if([...dirtyForms].some(other=>other!==form)&&!E.confirmLeave(true,'此保存会关闭其他表单尚未保存的填写。是否放弃其他填写并继续？'))return;const type=form.dataset.form;let c={type,name:form.elements.name.value};if(type==='rename')c.memberId=form.dataset.id;if(type==='meal'){if(!form.elements.consent.checked)return;const id=root.crypto?.randomUUID?.();if(!id){status('安全标识不可用，未保存。');return;}c={type,row:{id:'family-'+id,accountId:'demo-shen',memberId:state.health.family.selected,date:state.health.family.date,synthetic:true,name:c.name,time:form.elements.time.value,slot:form.elements.slot.value,kcal:null,carb:null,protein:null,fat:null,grams:null,source:'user-demo-entry'}};}void execute(c);});
page.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-refresh')){if(busy||!E.confirmLeave(dirty,'刷新会放弃未保存填写。'))return;try{render(S.read());}catch(err){status(err.message);}return;}const type=b.dataset.action;if(!type||busy||stale||E.hasPending())return;if(!E.confirmLeave(dirty,'此操作将放弃未保存填写。'))return;if(type==='delete'&&!root.confirm('归档该合成成员？记录保留，可恢复。'))return;void execute({type,memberId:b.dataset.id});});
page.addEventListener('change',e=>{if(!e.target.hasAttribute('data-date'))return;if(!E.confirmLeave(dirty,'切换日期会放弃未保存填写。')){e.target.value=state.health.family.date;return;}void execute({type:'date',date:e.target.value});});
root.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});root.addEventListener('pagehide',()=>{active=false;unsub?.();});
page.textContent='请先在共享入口确认合成演示…';try{await S.initialize({domains:['health'],guard});if(!active)return;render(S.read());unsub=S.subscribe(next=>{if(!active||busy||F.same(next,state))return;stale=true;status('资料已从其他页面更新，当前填写保留；请明确刷新。');disabled(true);});}catch(e){page.textContent='家庭入口未就绪：'+e.message+'。请重新加载后通过共享入口恢复，不会另建账号。';}
}
E.register('family-ui',{buildId:'registration-web-v3-c1',mount});})(window);
